#!/bin/bash
# Step 4: layouts of the optimized and the conventional cell library.
#   1. Magic: design-rule check and extraction of every cell
#   2. Netgen: layout versus schematic for every cell
#   3. Ngspice: every cell before and after layout with the Step 3 testbench
#      (1.8 V, FO4 load, every input transition, delay including the input driver)
# The layouts in mag/ are generated by step4_layout/gen_cells.py (not run here).
# Usage (from the repository root):  bash step4_layout/run.sh
cd "$(dirname "$0")" || exit 1
TECH=/apps/vlsi/share/qflow/tech/osu018
rm -rf out
mkdir -p out
python3 -c "import json; print(' '.join(c['name'] for c in json.load(open('cells.json'))['cells']))" > cells.txt
N=$(wc -w < cells.txt)

echo "[1/3] DRC and extraction of $N cells (magic)"
(cd out && magic -dnull -noconsole -rcfile ../../tech/magicrc ../cells.tcl > magic.log 2>&1)

echo "[2/3] LVS of $N cells (netgen)"
for c in $(cat cells.txt); do
    netgen -batch lvs "out/${c}_lvs.spice $c" "ref/$c.spice $c" \
        "$TECH/osu018_setup.tcl" "out/${c}_lvs.out" > "out/${c}_netgen.log" 2>&1
done

echo "[3/3] pre- and post-layout simulation of $N cells (ngspice), a few minutes"
python3 post_layout.py | tee out/summary.txt
